-- amargi– sengit pegatan ngandika Yéhuwah Gusti–Allah Israel lan–nutupi panganiaya ing– agemané ngandika Yéhuwah ingkang–Mahakuwasa lan–jagi–panjenengan ing–roh–panjenengan lan–boten cidra S

